package io.github.aedev.flow.ui.screens.player.state

import io.github.aedev.flow.player.state.SubtitleOption
import io.github.aedev.flow.player.stream.CaptionTrackResolver

internal object TranscriptTrackChoice {
    /**
     * The caption track a transcript reads.
     *
     * A pick made in the sheet for this video wins, then the subtitle that is showing, then the
     * transcript language picked last, the subtitle language, the app's language, and the spoken
     * language, which is the one the auto-generated track is in. The list leads with authored
     * tracks in alphabetical order, so taking its head opened a news video with English speech in
     * whichever other language sorted first (#1781).
     *
     * Language matches skip auto-translations, a machine pass over a track already in the list,
     * and prefer an authored track over an auto-generated one. A URL the current video has no
     * track for is dropped rather than fetched, so a queue advance cannot leave the panel reading
     * an empty URL.
     */
    fun pick(
        tracks: List<SubtitleOption>,
        pickedUrl: String?,
        showingUrl: String?,
        rememberedLanguage: String?,
        subtitleLanguage: String?,
        appLanguage: String?,
    ): SubtitleOption? {
        val readable = tracks.filter(::isReadable)
        val original = readable.filterNot { it.isTranslated }
        return readable.firstOrNull { pickedUrl != null && it.url == pickedUrl }
            ?: readable.firstOrNull { showingUrl != null && it.url == showingUrl }
            ?: inLanguage(original, rememberedLanguage)
            ?: inLanguage(original, subtitleLanguage)
            ?: inLanguage(original, appLanguage)
            ?: original.firstOrNull { it.isAutoGenerated }
            ?: original.firstOrNull()
            ?: readable.firstOrNull()
    }

    /** Only tracks fetched over the network can be read; files and tracks inside a video have no URL. */
    fun isReadable(track: SubtitleOption): Boolean = track.url.startsWith("http")

    /** The base language to remember when [url] is picked in the sheet, `en` for `en-US`. */
    fun languageToRemember(
        tracks: List<SubtitleOption>,
        url: String,
    ): String? =
        tracks
            .firstOrNull { it.url == url }
            ?.let { CaptionTrackResolver.baseLanguage(it.language) }
            ?.takeIf { it.isNotBlank() }

    private fun inLanguage(
        tracks: List<SubtitleOption>,
        languageTag: String?,
    ): SubtitleOption? {
        val (authored, autoGenerated) = tracks.partition { !it.isAutoGenerated }
        return match(authored, languageTag) ?: match(autoGenerated, languageTag)
    }

    private fun match(
        tracks: List<SubtitleOption>,
        languageTag: String?,
    ): SubtitleOption? =
        CaptionTrackResolver.bestMatch(
            candidates = tracks,
            languageTag = languageTag,
            tagOf = { it.language },
            isAutoGenerated = { it.isAutoGenerated },
        )
}
